triggers.definition:
CREATE TRIGGER attach_initial_work_context
AFTER INSERT ON public.work_events
FOR EACH ROW EXECUTE FUNCTION private.attach_initial_work_context();

CREATE TRIGGER enforce_autonomous_intelligence_on_claim
BEFORE INSERT ON public.work_claims
FOR EACH ROW EXECUTE FUNCTION private.enforce_autonomous_intelligence_on_claim();

CREATE TRIGGER enforce_autonomous_intelligence_on_attempt
BEFORE INSERT ON public.work_events
FOR EACH ROW EXECUTE FUNCTION private.enforce_autonomous_intelligence_on_attempt();

CREATE TRIGGER enforce_autonomous_routing_on_attempt
BEFORE INSERT ON public.work_events
FOR EACH ROW EXECUTE FUNCTION private.enforce_autonomous_routing_on_attempt();

CREATE TRIGGER enforce_adjustment_on_routing_decision
BEFORE INSERT ON public.work_events
FOR EACH ROW EXECUTE FUNCTION private.enforce_adjustment_on_routing_decision();

CREATE TRIGGER enforce_autonomous_work_budget_before_start
BEFORE INSERT ON public.work_events
FOR EACH ROW EXECUTE FUNCTION private.enforce_autonomous_work_budget();

CREATE TRIGGER guard_mandated_review_release
  BEFORE UPDATE OF state ON public.work_items
  FOR EACH ROW EXECUTE FUNCTION private.guard_mandated_review_release();

CREATE TRIGGER guard_trusted_system_fact
  BEFORE INSERT OR UPDATE ON public.work_events
  FOR EACH ROW EXECUTE FUNCTION private.guard_trusted_system_fact();

CREATE TRIGGER work_items_verifier_requirement_monotonic
  BEFORE UPDATE OF intent ON public.work_items
  FOR EACH ROW EXECUTE FUNCTION private.guard_verifier_requirement_monotonic();

