INSERT INTO public.work_items (
    user_id, source_message_id, state, impact_level, capability,
    original_request, intent, proposal, proposal_version
  ) VALUES (
    v_user_id, source_message_id, 'proposed', impact_level, capability,
    v_original_request, intent, proposal, 1
  )
  RETURNING * INTO v_item;

INSERT INTO public.work_events (
    work_item_id, event_type, author, proposal_version, payload
  ) VALUES (
    v_item.id,
    'work_proposed',
    'anima',
    v_item.proposal_version,
    jsonb_build_object(
      'schema_version', 1,
      'data', jsonb_build_object('proposal', proposal)
    )
  );

INSERT INTO public.work_events (
    work_item_id, event_type, author, proposal_version, payload
  ) VALUES (
    v_item.id,
    'proposal_revised',
    'anima',
    v_item.proposal_version,
    jsonb_build_object(
      'schema_version', 1,
      'data', jsonb_build_object('proposal', proposal)
    )
  );

INSERT INTO public.work_events (
    work_item_id, event_type, author, proposal_version, payload
  ) VALUES (
    v_item.id,
    'work_started',
    'user',
    v_item.proposal_version,
    jsonb_build_object('schema_version', 1, 'data', jsonb_build_object())
  );

INSERT INTO public.work_events (
    work_item_id, event_type, author, proposal_version, payload
  ) VALUES (
    v_item.id,
    'result_submitted',
    'user',
    v_item.proposal_version,
    jsonb_build_object(
      'schema_version', 1,
      'data', result
    )
  );

INSERT INTO public.work_events (
    work_item_id, event_type, author, proposal_version, payload
  ) VALUES (
    v_item.id,
    v_event,
    'user',
    v_item.proposal_version,
    jsonb_build_object('schema_version', 1, 'data',
      CASE decision
        WHEN 'accept' THEN jsonb_build_object(
          'accepted_result_event_id', v_result_event_id
        )
        WHEN 'request_changes' THEN jsonb_build_object(
          'requested_changes', decision_context ->> 'requested_changes',
          'reviewed_proposal_version', v_item.proposal_version,
          'reviewed_result_event_id', v_result_event_id
        )
      END
    )
  );

SELECT * INTO v_item FROM public.work_items AS item
  WHERE item.id = work_item_id AND item.user_id = v_user_id
  FOR UPDATE;

INSERT INTO public.work_contexts (work_item_id, version, context_references)
  VALUES (v_item.id, v_version, context_references)
  RETURNING * INTO v_context;

INSERT INTO public.work_contexts(work_item_id,version,context_references)
  VALUES(v_item.id,1,jsonb_build_array(jsonb_build_object('kind','message','id',v_item.source_message_id::text)))
  RETURNING * INTO v_context;

INSERT INTO public.work_events(work_item_id,event_type,author,proposal_version,payload)
  VALUES(v_item.id,v_event,'executor'::public.work_event_author,
    v_item.proposal_version,jsonb_build_object('schema_version',1,'data',v_data));

SELECT * INTO v_open FROM public.work_claims c
  WHERE c.user_id=v_user_id AND c.target_reference=v_target AND c.released_at IS NULL
  FOR UPDATE;

INSERT INTO public.work_claims(id,work_item_id,user_id,approved_proposal_version,owner_instance_id,acquired_at,expires_at,target_reference)
  VALUES (claim_id,v_item.id,v_user_id,expected_proposal_version,v_owner,v_now,v_now + make_interval(secs => lease_seconds),v_target)
  RETURNING * INTO v_claim;

SELECT * INTO v_claim FROM public.work_claims c
   WHERE c.user_id=v_uid AND c.work_item_id=v_item.id
     AND c.attempt_id=p_attempt_id AND c.released_at IS NULL FOR UPDATE;

SELECT * INTO v_claim FROM public.work_claims c
   WHERE c.user_id=v_uid AND c.work_item_id=v_item.id
     AND c.attempt_id=p_attempt_id AND c.released_at IS NULL FOR UPDATE;

INSERT INTO public.work_events(work_item_id, event_type, author, proposal_version, payload)
  VALUES (v_item.id, 'work_proposed', 'anima', 1,
    jsonb_build_object('schema_version', 1, 'data', jsonb_build_object('proposal', p_proposal)));

INSERT INTO public.work_events (
    work_item_id, event_type, author, proposal_version, payload
  ) VALUES (
    v_item.id,
    'work_cancelled',
    'user',
    v_item.proposal_version,
    jsonb_build_object('schema_version', 1, 'data', jsonb_build_object(
      'reason', btrim(reason),
      'withdrawn_before_execution', true,
      'withdrawn_from_state', 'approved'
    ))
  );

INSERT INTO public.work_events(work_item_id,event_type,author,proposal_version,payload)
  VALUES(v_item.id,'integration_effect_authorized','user',expected_proposal_version,jsonb_build_object('schema_version',1,'data',v_data))
  RETURNING seq INTO v_seq;

INSERT INTO public.work_events(work_item_id, event_type, author, proposal_version, payload)
  VALUES (v_item.id, v_event, 'user', v_item.proposal_version,
    jsonb_build_object('schema_version', 1, 'data', v_data));
